alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.friendships
    where
      (requester_id = p_user_id or addressee_id = p_user_id)
      and status = 'accepted'
      and (requester_id <> p_user_id or addressee_id <> p_user_id)
  );
$$;

revoke execute on function public.is_friend(uuid) from public, anon;
grant execute on function public.is_friend(uuid) to authenticated, service_role;

create policy "friendships_select_own_or_addressee"
on public.friendships
for select
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy "friendships_insert_own_pending"
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
  and requester_id <> addressee_id
);

create policy "friendships_update_addressee_accept"
on public.friendships
for update
to authenticated
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
);

create policy "friendships_delete_own"
on public.friendships
for delete
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy "posts_select_public_friends_own"
on public.posts
for select
to anon, authenticated
using (
  (audience = 'public')
  or (audience = 'friends' and public.is_friend(auth.uid()))
  or (author_id = auth.uid())
);

create policy "posts_insert_own"
on public.posts
for insert
to authenticated
with check (
  author_id = auth.uid()
);

create policy "posts_update_own"
on public.posts
for update
to authenticated
using (
  author_id = auth.uid()
)
with check (
  author_id = auth.uid()
);

create policy "posts_delete_own"
on public.posts
for delete
to authenticated
using (
  author_id = auth.uid()
);

revoke insert, update, delete on table public.friendships from anon;
grant insert, update, delete on table public.friendships to authenticated;

revoke insert, update, delete on table public.posts from anon;
grant insert, update, delete on table public.posts to authenticated;
