create or replace function public.enforce_file_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.legal_hold is distinct from false then
      raise exception 'legal_hold can only be set by server-side code';
    end if;
    if new.owner_id is distinct from auth.uid() then
      raise exception 'files must be owned by the uploader';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.legal_hold is distinct from old.legal_hold then
      raise exception 'legal_hold can only be changed by server-side code';
    end if;
    if new.owner_id is distinct from old.owner_id then
      raise exception 'file owner cannot be changed';
    end if;
    if new.name is distinct from old.name then
      if old.legal_hold then
        raise exception 'cannot rename a file under legal hold';
      elsif auth.role() = 'authenticated' then
        if (select auth.uid()) is distinct from old.owner_id
           and not exists (
             select 1
             from public.org_admins
             where user_id = auth.uid()
           ) then
          raise exception 'not allowed to rename this file';
        end if;
      end if;
    end if;
    if new.legal_hold then
      raise exception 'legal_hold can only be changed by server-side code';
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_file_guard
before insert or update on public.files
for each row execute function public.enforce_file_guard();
