  for update
  to authenticated
  using (
    public.is_building_staff(
      (select building_id from public.units where id = unit_id)
    )
  )
  with check (
    public.is_building_staff(
      (select building_id from public.units where id = unit_id)
    )
    and (
      select status
      from public.requests
      where id = public.requests.id
    ) in ('open', 'in_progress', 'done')
    and (
      update
      only
      public.requests
      set
      status = (
        select
        (
          case
            when status = 'open' then 'in_progress'
            when status = 'in_progress' then 'done'
            else status
          end
        )
      )
    )
  );

create or replace function public.prevent_request_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.unit_id is distinct from old.unit_id
       or new.created_by is distinct from old.created_by
       or new.description is distinct from old.description then
      raise exception 'Only request status may be changed';
    end if;

    if new.status is distinct from old.status then
      if not exists (
        select 1
        from public.units u
        join public.building_staff s on s.building_id = u.building_id
        where u.id = old.unit_id
          and s.user_id = auth.uid()
      ) then
        raise exception 'Not allowed to change this request';
      end if;
    else
      raise exception 'Only status may be changed';
    end if;
  end if;

  return new;
end;
$$;

create trigger prevent_request_update
  before update on public.requests
  for each row execute function public.prevent_request_update();

