create or replace function public.enforce_class_spots_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if auth.uid() is distinct from current_user then
    raise exception 'Not authenticated';
  end if;

  if tg_op = 'UPDATE' then
    if new.class_id is distinct from old.class_id
       or new.user_id is distinct from old.user_id then
      raise exception 'class_id and user_id cannot be changed';
    end if;

    if new.status is distinct from old.status then
      if old.status <> 'waitlisted'
         or new.status <> 'enrolled' then
        raise exception 'Invalid status transition';
      end if;

      if not exists (
        select 1
        from public.classes c
        where c.id = new.class_id
          and c.instructor_id = auth.uid()
          and (
            select count(*)
            from public.class_spots s
            where s.class_id = c.id
              and s.status = 'enrolled'
          ) < c.capacity
      ) then
        raise exception 'No room to move up';
      end if;
    end if;

    return new;
  elsif tg_op = 'DELETE' then
    if old.user_id is distinct from auth.uid() then
      raise exception 'Not allowed';
    end if;

    if not exists (
      select 1
      from public.classes c
      where c.id = old.class_id
        and c.instructor_id = auth.uid()
    ) then
      raise exception 'Not allowed';
    end if;

    return old;
  end if;

  return new;
end;
$$;

create trigger class_spots_enforce_update
  after update on public.class_spots
  for each row execute function public.enforce_class_spots_update();

